import type { WasmFeatures } from "../../platform/platformCapabilities";
import { getPlatformCapabilities } from "../../platform/platformCapabilities";
import { getPlatformInfo } from "../../platform/platformInfo";
import { extractVersion } from "../../common/version";

const wasmAssets = ["LensCoreWebAssembly.js", "LensCoreWebAssembly.wasm"];

export function getBuildFlavor({ simd, relaxedSimd }: WasmFeatures, versionNumber: string) {
    // Starting from approx build 282, LensCore now includes relaxed builds.
    // We need to check for this because we allow customization of Camera Kit
    // with any LensCore builds, which may not include a relaxed build.
    const relaxedBuildAvailable = extractVersion(versionNumber).major >= 282;
    if (relaxedBuildAvailable && relaxedSimd) {
        return "rel-relaxed-simd-neh";
    } else if (simd) {
        return "rel-simd-neh";
    } else {
        return "rel-neh";
    }
}

/**
 * URLs of the WebAssembly assets required to run the rendering engine: the WebAssembly binary
 * and its JS glue file. Accepted by the `lensCoreOverrideUrls` configuration option and produced
 * by {@link createBootstrapURLs}.
 *
 * @category Bootstrapping and Configuration
 */
export interface WasmAssetUrls {
    js: string;
    wasm: string;
}

/**
 * Builds bootstrap asset URLs for a custom-hosted build of the rendering engine.
 *
 * @param endpoint URL of the build root — the directory containing the build-flavor directories.
 * May be absolute or relative to the current page (e.g. `/assets/builds`). Any query string on the
 * endpoint is preserved on the returned asset URLs.
 * @param flavor Optional build flavor to force. When omitted, the optimal flavor for the current
 * platform is detected — the same selection the SDK performs for its own CDN. Note that forcing a
 * flavor bypasses capability detection: the caller is responsible for choosing one the current
 * browser can run.
 * @returns Asset URLs suitable for passing to the `lensCoreOverrideUrls` configuration option.
 *
 * @category Bootstrapping and Configuration
 */
export async function createBootstrapURLs(endpoint: string, flavor?: string): Promise<WasmAssetUrls> {
    let resolvedFlavor = flavor;
    if (resolvedFlavor === undefined) {
        const { wasm } = await getPlatformCapabilities();
        if (!wasm.supported) throw wasm.error;
        resolvedFlavor = getBuildFlavor(wasm.wasmFeatures, getPlatformInfo().lensCore.version);
    }

    // A dummy base makes `new URL` accept page-relative endpoints; it only affects the
    // parts we don't read. The path is taken from the raw string to keep it verbatim.
    const { search } = new URL(endpoint, "http://relative.invalid");
    const path = endpoint.split(/[?#]/)[0].replace(/\/+$/, "");
    const base = `${path}/${resolvedFlavor}`;
    return {
        js: `${base}/LensCoreWebAssembly.js${search}`,
        wasm: `${base}/LensCoreWebAssembly.wasm${search}`,
    };
}

/**
 * Returns a list of URLs for resources which will be fetched during {@link bootstrapCameraKit}.
 *
 * When CameraKit is used on a website, these URLs must be reachable in order for CameraKit to be successfully
 * bootstrapped.
 *
 * @returns An array of asset URLs.
 *
 * @category Bootstrapping and Configuration
 */
export async function getRequiredBootstrapURLs(): Promise<string[]>;
/**
 * @param endpointOverride Endpoint override to load the assets from. The assets are expected to live
 * directly at this endpoint, without build-flavor directories.
 *
 * @deprecated Passing `endpointOverride` is deprecated — use {@link createBootstrapURLs} to construct
 * URLs for a custom endpoint instead.
 */
export async function getRequiredBootstrapURLs(endpointOverride: string | undefined): Promise<string[]>;
export async function getRequiredBootstrapURLs(endpointOverride?: string): Promise<string[]> {
    // If we have an endpoint override, remove trailing `/` so we can construct a valid URL.
    const endpoint = endpointOverride?.replace(/[\/]+$/, "");

    const { wasm } = await getPlatformCapabilities();
    if (!wasm.supported) throw wasm.error;

    const { lensCore } = getPlatformInfo();
    const version = lensCore.version;
    const buildNumber = lensCore.buildNumber;
    const flavor = getBuildFlavor(wasm.wasmFeatures, version);
    return wasmAssets.map((asset) => {
        if (endpoint) return `${endpoint}/${asset}`;
        const { origin, pathname, search } = new URL(lensCore.baseUrl);
        return `${origin}${pathname}/${version}/${buildNumber}/${flavor}/${asset}${search}`;
    });
}
